-- ============================================================
-- Autumn Gateway Dashboard — PostgreSQL 兼容表结构
-- 与 schema-mysql.sql 语义一致，仅 DDL 语法适配 PostgreSQL：
--   AUTO_INCREMENT        -> GENERATED BY DEFAULT AS IDENTITY
--   TINYINT               -> SMALLINT
--   DATETIME              -> TIMESTAMP
--   去掉 ENGINE / CHARSET / COLLATE / ON UPDATE CURRENT_TIMESTAMP / 内联 COMMENT
--   保留字 user 使用双引号 "user"
--   UNIQUE KEY / INDEX    -> CONSTRAINT ... UNIQUE / CREATE INDEX IF NOT EXISTS
--
-- 说明：外键改为建表内联声明（配合 CREATE TABLE IF NOT EXISTS 保证幂等），
--       CREATE INDEX 统一加 IF NOT EXISTS，避免 spring.sql.init.mode=always
--       在第二次启动时因"对象已存在"而初始化失败。
-- ============================================================

-- 1. 应用（多应用隔离）
CREATE TABLE IF NOT EXISTS application (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  appid       VARCHAR(64) NOT NULL,
  name        VARCHAR(64) NOT NULL,
  base_path   VARCHAR(128),
  description VARCHAR(255),
  status      SMALLINT DEFAULT 1,
  created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_appid UNIQUE (appid)
);
CREATE INDEX IF NOT EXISTS idx_application_status ON application(status);

-- 2. 用户（全局共享，user 为保留字，需双引号）
CREATE TABLE IF NOT EXISTS "user" (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  uuid          VARCHAR(36) NOT NULL,
  username      VARCHAR(64) UNIQUE,
  nickname      VARCHAR(64),
  avatar        VARCHAR(255),
  email         VARCHAR(128),
  phone         VARCHAR(32),
  emp_no        VARCHAR(64),
  status        SMALLINT DEFAULT 1,
  password_updated_at TIMESTAMP,
  last_login_at TIMESTAMP,
  created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_uuid UNIQUE (uuid)
);
CREATE INDEX IF NOT EXISTS idx_user_email ON "user"(email);
CREATE INDEX IF NOT EXISTS idx_user_phone ON "user"(phone);
CREATE INDEX IF NOT EXISTS idx_user_status ON "user"(status);

-- 3. 用户在哪些应用下有身份
CREATE TABLE IF NOT EXISTS user_app (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT NOT NULL,
    app_id     BIGINT NOT NULL,
    is_admin   SMALLINT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_user_app UNIQUE (user_id, app_id),
    FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE CASCADE,
    FOREIGN KEY (app_id) REFERENCES application(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_user_app_app_user ON user_app(app_id, user_id);
CREATE INDEX IF NOT EXISTS idx_user_app_user ON user_app(user_id);

-- 4. 认证账户（统一存储多种认证方式）
CREATE TABLE IF NOT EXISTS user_auth_account (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id       BIGINT NOT NULL,
  identity_type VARCHAR(32) NOT NULL,
  identifier    VARCHAR(255) NOT NULL,
  credential    VARCHAR(512),
  issuer        VARCHAR(255),
  expires_at    TIMESTAMP,
  refresh_token TEXT,
  union_id      VARCHAR(255),
  verified      SMALLINT DEFAULT 0,
  credential_updated_at TIMESTAMP,
  created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_type_identifier UNIQUE (identity_type, identifier),
  CONSTRAINT uk_issuer_type_identifier UNIQUE (issuer, identity_type, identifier),
  FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_auth_user ON user_auth_account(user_id);
CREATE INDEX IF NOT EXISTS idx_auth_union_id ON user_auth_account(union_id);

-- 5. 权限/资源（合并 RBAC Permission + Wolf Resource）
CREATE TABLE IF NOT EXISTS permission (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  app_id        BIGINT NOT NULL,
  category      VARCHAR(64),
  code          VARCHAR(128) NOT NULL,
  name          VARCHAR(64),
  perm_type     VARCHAR(16) DEFAULT 'API',
  resource_path VARCHAR(255),
  http_method   VARCHAR(16) DEFAULT 'ALL',
  match_type    VARCHAR(16) DEFAULT 'exact',
  parent_id     BIGINT DEFAULT 0,
  icon          VARCHAR(64),
  sort          INT DEFAULT 0,
  hidden        SMALLINT DEFAULT 0,
  description   VARCHAR(255),
  status        SMALLINT DEFAULT 1,
  created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_app_code UNIQUE (app_id, code),
  FOREIGN KEY (app_id) REFERENCES application(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_perm_type ON permission(perm_type);
CREATE INDEX IF NOT EXISTS idx_perm_status ON permission(status);
CREATE INDEX IF NOT EXISTS idx_perm_parent ON permission(parent_id);

-- 6. 角色（RBAC 的 R）
CREATE TABLE IF NOT EXISTS role (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  app_id      BIGINT NOT NULL,
  code        VARCHAR(64) NOT NULL,
  name        VARCHAR(64) NOT NULL,
  description VARCHAR(255),
  status      SMALLINT DEFAULT 1,
  created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_app_role_code UNIQUE (app_id, code),
  FOREIGN KEY (app_id) REFERENCES application(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_role_status ON role(status);

-- 7. 用户授角色（含应用上下文）
CREATE TABLE IF NOT EXISTS user_role (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    BIGINT NOT NULL,
  role_id    BIGINT NOT NULL,
  app_id     BIGINT NOT NULL,
  expires_at TIMESTAMP,
  created_by BIGINT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_user_role_app UNIQUE (user_id, role_id, app_id),
  FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE CASCADE,
  FOREIGN KEY (role_id) REFERENCES role(id) ON DELETE CASCADE,
  FOREIGN KEY (app_id) REFERENCES application(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_user_role_role ON user_role(role_id);
CREATE INDEX IF NOT EXISTS idx_user_role_app ON user_role(app_id);

-- 8. 角色赋权
CREATE TABLE IF NOT EXISTS role_permission (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_id       BIGINT NOT NULL,
  permission_id BIGINT NOT NULL,
  created_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_role_perm UNIQUE (role_id, permission_id),
  FOREIGN KEY (role_id) REFERENCES role(id) ON DELETE CASCADE,
  FOREIGN KEY (permission_id) REFERENCES permission(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_role_perm_perm ON role_permission(permission_id);

-- 9. 审计日志（不可变，只追加不修改）
CREATE TABLE IF NOT EXISTS audit_log (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  app_id     BIGINT,
  user_id    BIGINT,
  action     VARCHAR(64),
  resource   VARCHAR(1024),
  method     VARCHAR(16),
  status     SMALLINT,
  reason     VARCHAR(256),
  client_ip  VARCHAR(45),
  user_agent TEXT,
  request_id VARCHAR(36),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_log(user_id);
CREATE INDEX IF NOT EXISTS idx_audit_app_time ON audit_log(app_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_created_at ON audit_log(created_at);
CREATE INDEX IF NOT EXISTS idx_audit_request_id ON audit_log(request_id);
